3637	        bool hasText = kind == kKindText || kind == kKindButton || kind == kKindTextInput ||
3638	            kind == kKindIntegerInput || kind == kKindBooleanInput || kind == kKindMultiline;
3639	        if (!hasText) return;
3640	        uint32_t textColor = packColor(node.pod.textRed, node.pod.textGreen, node.pod.textBlue,
3641	                                       node.pod.textAlpha);
3642	        std::string text = displayTextForNode(node);
3643	        bool isEditingNode = false;
3644	        bool showCaret = false;
3645	        int64_t caretContext = 0;
3646	        int32_t caretAffinity = 0;
3647	        const bool foreground = !g_ingress.foregroundLevel || g_ingress.foregroundLevel() == 1;
3648	        std::u16string editComposed;
3649	        uint32_t selStartUtf16 = 0;
3650	        uint32_t selEndUtf16 = 0;
3651	        uint32_t caretUtf16 = 0;
3652	        {
3653	            std::lock_guard<std::mutex> g(g_sessions.lock);
3654	            // 绘制当前会话的编辑视图：渲染线程是编辑缓冲绘制归属方；
3655	            // 只有绑定本节点的活跃编辑覆盖静态 value。
3656	            for (size_t i = 0; i < kMaxSessions; ++i) {
3657	                Session &sess = g_sessions.sessions[i];
3658	                if (sess.inUse && sess.token == frameSession && sess.editing &&
3659	                    sess.editingNodeId == node.pod.nodeId && sess.editingResourceId == node.pod.resourceId &&
3660	                    sess.editingNodeKind == node.pod.nodeKind) {
3661	                    // Match binding continuity across the legal Flush→accepted
3662	                    // interval, without borrowing another Session or requiring
3663	                    // equality with a projection not yet settled by the owner.
3664	                    bool sameBinding = false;
3665	                    for (const SceneNode &accepted : sess.accepted) {
3666	                        if (accepted.pod.nodeId == node.pod.nodeId && accepted.pod.resourceId == node.pod.resourceId &&
3667	                            accepted.pod.nodeKind == node.pod.nodeKind && node.pod.acceptedBindingEpoch != 0 &&
3668	                            accepted.pod.acceptedBindingEpoch == node.pod.acceptedBindingEpoch) {
3669	                            sameBinding = true;
3670	                            break;
3671	                        }
3672	                    }
3673	                    if (!sameBinding) break;
3674	                    // 逻辑编辑已结束（retired）时本地缓冲只用来补核心「本地文字延续」
3675	                    // 窗口内的空投影（约定由原生编辑器绘制该节点）。一旦 accepted 已经
3676	                    // 给出这个节点的值，那就是 owner 的裁决——包括本地编辑被拒、owner
3677	                    // 保留外部值的情形——不得再被本地缓冲遮盖，否则一次被拒的提交会
3678	                    // 让字段持续显示那个草稿。
3679	                    // C：本地文字延续窗口由显式旗标（preservesActiveLocalText）
3680	                    // 判定——accepted 值为空只是业务空值，不得推断为延续窗口。
3681	                    if (sess.editorRetired && node.pod.preservesActiveLocalText == 0) break;
3682	                    isEditingNode = true;
3683	                    editComposed = composedBuffer(sess);
3684	                    text = utf16ToUtf8(editComposed);
3685	                    if (text.empty()) text = " ";  // 空缓冲也绘制光标
3686	                    // 选区只取事实；高亮在字形排版（同一原点/行高）之后绘制，
3687	                    // 否则框与字符来自两个不同的 y 基线。
3688	                    selStartUtf16 = std::min(sess.selStartUtf16, sess.selEndUtf16);
3689	                    selEndUtf16 = std::max(sess.selStartUtf16, sess.selEndUtf16);
3690	                    caretUtf16 = std::min(sess.caretUtf16, static_cast<uint32_t>(editComposed.size()));
3691	                    caretAffinity = sess.caretAffinity;
3692	                    caretContext = sess.editingContextId;
3693	                    showCaret = foreground && !sess.editorRetired && sess.editingContextLive &&
3694	                        selStartUtf16 == selEndUtf16 && (sess.caretBlinkResetPending || sess.caretBlinkVisible);
3695	                    break;
3696	                }
3697	            }
3698	        }
3699	        if (text.empty()) return;
3700	        Measured m = layoutText(text, node.pod.fontSize, node.pod.fontWeight,
3701	                                static_cast<double>(node.pod.width), false, textColor);
3702	        if (!m.typography) return;
3703	        TextGeometry geom = computeTextGeometry(static_cast<double>(node.pod.x),
3704	                                                static_cast<double>(node.pod.y),
3705	                                                static_cast<double>(node.pod.height), kind, m,
3706	                                                node.pod.fontSize);
