3710	        }
3711	        OH_Drawing_TypographyPaint(m.typography, canvas, geom.originX, geom.originY);
3712	        // 光标（仅编辑节点；矩形由排版给出，落在真正被命中的那一行）
3713	        if (isEditingNode && showCaret) {
3714	            const uint32_t caret = caretUtf16;
3715	            double caretX = 0.0;
3716	            double caretTop = 0.0;
3717	            double caretBottom = geom.lineHeight;
3718	            if (!caretRectFor(m.typography, caret, editComposed, caretAffinity,
3719	                              caretX, caretTop, caretBottom)) {
3720	                // 拒答不能变成首行 longestLine 的假落点；正文仍照常绘制。
