3722	                OH_Drawing_DestroyTypography(m.typography);
3723	                return;
3724	            }
3725	            RLOGI("caret geometry session=%{public}llu ctx=%{public}lld caret=%{public}u affinity=%{public}d "
3726	                "x=%{public}.3f top=%{public}.3f bottom=%{public}.3f",
3727	                static_cast<unsigned long long>(frameSession), static_cast<long long>(caretContext), caret,
3728	                caretAffinity, geom.originX + caretX, geom.originY + caretTop, geom.originY + caretBottom);
3729	            OH_Drawing_Brush *cb = OH_Drawing_BrushCreate();
3730	            OH_Drawing_BrushSetColor(cb, packColor(0.65, 0.85, 1.0, 1.0));
3731	            OH_Drawing_CanvasAttachBrush(canvas, cb);
3732	            OH_Drawing_Rect *caretRect = OH_Drawing_RectCreate(
3733	                static_cast<float>(geom.originX + caretX - 1.0),
3734	                static_cast<float>(geom.originY + caretTop),
3735	                static_cast<float>(geom.originX + caretX + 1.0),
3736	                static_cast<float>(geom.originY + caretBottom));
3737	            OH_Drawing_CanvasDrawRect(canvas, caretRect);
3738	            OH_Drawing_RectDestroy(caretRect);
3739	            OH_Drawing_CanvasDetachBrush(canvas);
3740	            OH_Drawing_BrushDestroy(cb);
3741	        }
3742	        OH_Drawing_DestroyTypography(m.typography);
3743	    }
