3754	    Measured layoutText(const std::string &text, double fontSize, uint32_t fontWeight,
3755	                        double constraintWidth, bool unlimitedWidth, uint32_t textColor)
3756	    {
3757	        Measured result;
3758	        OH_Drawing_TypographyStyle *style = OH_Drawing_CreateTypographyStyle();
3759	        OH_Drawing_TextStyle *textStyle = OH_Drawing_CreateTextStyle();
3760	        OH_Drawing_SetTextStyleFontSize(textStyle, fontSize);
3761	        OH_Drawing_SetTextStyleFontWeight(textStyle, mapWeight(fontWeight));
3762	        // 共同定义的前景色由节点携带，后端不重新指定颜色。
3763	        OH_Drawing_SetTextStyleColor(textStyle, textColor);
3764	        const char *family = "HarmonyOS Sans";
3765	        OH_Drawing_SetTextStyleFontFamilies(textStyle, 1, &family);
3766	        OH_Drawing_TypographyCreate *handler =
3767	            OH_Drawing_CreateTypographyHandler(style, OH_Drawing_GetFontCollectionGlobalInstance());
3768	        OH_Drawing_TypographyHandlerPushTextStyle(handler, textStyle);
3769	        OH_Drawing_TypographyHandlerAddText(handler, text.c_str());
3770	        OH_Drawing_TypographyHandlerPopTextStyle(handler);
3771	        result.typography = OH_Drawing_CreateTypography(handler);
3772	        OH_Drawing_DestroyTypographyHandler(handler);
3773	        OH_Drawing_DestroyTextStyle(textStyle);
3774	        OH_Drawing_DestroyTypographyStyle(style);
3775	        if (!result.typography) return result;
3776	        double layoutWidth = unlimitedWidth ? 1000000.0 : constraintWidth;
3777	        if (layoutWidth < 1.0) layoutWidth = 1.0;
3778	        OH_Drawing_TypographyLayout(result.typography, layoutWidth);
3779	        result.height = OH_Drawing_TypographyGetHeight(result.typography);
3780	        result.longestLine = OH_Drawing_TypographyGetLongestLine(result.typography);
3781	        result.maxWidth = OH_Drawing_TypographyGetMaxWidth(result.typography);
3782	        result.lineCount = OH_Drawing_TypographyGetLineCount(result.typography);
3783	        result.alphabeticBaseline = OH_Drawing_TypographyGetAlphabeticBaseline(result.typography);
3784	        return result;
3785	    }
