6928	static void syncEditingBufferAfterAcceptedSceneLocked(Session *s)
6929	{
6930	    if (!s->editing) return;
6931	    bool found = false;
6932	    for (const SceneNode &n : s->accepted) {
6933	        if (n.pod.nodeId != s->editingNodeId || n.pod.resourceId != s->editingResourceId) continue;
6934	        found = true;
6935	        if (n.pod.nodeKind != s->editingNodeKind ||
6936	            n.semanticId != s->editingFieldName ||
6937	            n.pod.isReadOnly != 0 || n.pod.isInteractive == 0) {
6938	            s->pendingImeDetach = true;  // 换绑/禁用：旧上下文失效
6939	            s->pendingSettleOnDetach = false;
6940	            s->editing = false;          // 节点不可编辑：连同绘制一起结束
6941	            s->editorRetired = true;
6942	            s->editingContextLive = false;
6943	            s->previewActive = false;
6944	            s->previewText.clear();
6945	            s->markedActive = false;
6946	            s->reconcileNotifyPending = false;
6947	            cancelProxyRestoreRequest(*s, "rebound_kind_or_field");
6948	            break;
6949	        }
6950	        std::u16string ownerValue = utf8ToUtf16(n.value);
6951	        // The core marks a locally accepted text event explicitly and stages an
6952	        // empty native value so the active editor keeps drawing the event text.
6953	        // Its scene version advances too: carry that admission version forward
6954	        // without retiring this context or mistaking the staged empty value for
6955	        // an external replacement (including a legitimate empty local edit).
6956	        if (n.pod.preservesActiveLocalText != 0) {
6957	            s->editingContextBaseVersion = n.pod.projectionVersion;
6958	            s->editingProjectionVersion = n.pod.projectionVersion;
6959	            break;
6960	        }
6961	        // H1-C：本地编辑被 owner 接受后，accepted 投影带回的就是屏幕上这段文本
6962	        // （ownerValue == 编辑缓冲）。这是同一段本地连续的准入版本推进，不是外部
6963	        // 换版：只推进版本并保留平台光标/组合态。否则每敲一个字都要重建编辑
6964	        // 上下文并让页面重挂系统输入代理，光标与 preedit 全部丢失。
6965	        if (s->editingContextLive && !s->previewActive &&
6966	            n.pod.projectionVersion != s->editingContextBaseVersion &&
6967	            ownerValue == s->editingText) {
6968	            s->editingContextBaseVersion = n.pod.projectionVersion;
6969	            s->editingProjectionVersion = n.pod.projectionVersion;
6970	            break;
6971	        }
6972	        if (s->editingContextLive &&
6973	            n.pod.projectionVersion != s->editingContextBaseVersion) {
6974	            // projectionVersion 与 editingContextBaseVersion 均取本节点入场时
6975	            // 的同一 scene.version；它是当前输入事件的准入版本。新 accepted
6976	            // 版本使旧整值草稿失效，不以字符串相等推断事务仍有效。
6977	            int64_t oldContext = s->editingContextId;
6978	            if (!s->reconcileNotifyPending) s->reconcileOldContextId = oldContext;
6979	            // 外部换版：新上下文编号即新身份，旧恢复请求（连同待发正文/选区）作废，
6980	            // 否则旧恢复串会带着旧上下文号落到新上下文上。
6981	            cancelProxyRestoreRequest(*s, "external_version");
6982	            s->editingContextId = g_nextEditingContextId.fetch_add(1);
6983	            s->caretBlinkResetPending = true;
6984	            s->caretAffinity = 0;
6985	            s->editingContextBaseVersion = n.pod.projectionVersion;
6986	            s->editingProjectionVersion = n.pod.projectionVersion;
6987	            s->editingFieldName = n.semanticId;
6988	            s->editingText = ownerValue;
6989	            s->previewActive = false;
6990	            s->previewText.clear();
6991	            s->markedActive = false;
6992	            s->markedStart = 0;
6993	            s->markedEnd = 0;
6994	            s->pendingSettleOnDetach = false;
6995	            s->caretUtf16 = static_cast<uint32_t>(ownerValue.size());
6996	            s->selStartUtf16 = s->caretUtf16;
6997	            s->selEndUtf16 = s->caretUtf16;
6998	            s->editingTapPending = false;
6999	            // 如果最初的 focus 还未送达，直接发送新 context 的 focus；
7000	            // 否则发送 reconcile，供页面先卸旧 TextInput 再挂新实例。
7001	            if (!s->focusNotifyPending) s->reconcileNotifyPending = true;
7002	            RLOGI("ime context reconcile old=%{public}lld new=%{public}lld base=%{public}llu",
7003	                  static_cast<long long>(oldContext),
7004	                  static_cast<long long>(s->editingContextId),
7005	                  static_cast<unsigned long long>(s->editingContextBaseVersion));
7006	            g_render.post(std::make_shared<RedrawJob>());
7007	            break;
7008	        }
7009	        if (s->previewActive) break;
7010	        // 核心的「本地文字延续」窗口会把 native 值置空，约定由原生编辑器
7011	        // 绘制可见文本（macOS 用输入代理字符串做同一件事）。这里的空值不是
7012	        // 业务空值，用它同步会清掉本地缓冲，使随后任何纯重绘把字段画成空白。
7013	        // C：延续窗口必须由显式旗标判定。owner 值为空且节点未打延续旗标 =
7014	        // 业务空值（外部清空/合法空提交）——必须同步清空本地缓冲，
7015	        // 不得凭「owner 空 + 缓冲非空」推断为延续。
7016	        bool blankedByLocalContinuation = ownerValue.empty() && !s->editingText.empty()
7017	            && n.pod.preservesActiveLocalText != 0;
7018	        if (!blankedByLocalContinuation && ownerValue != s->editingText) {
7019	            s->editingText = ownerValue;
7020	        }
7021	        s->caretUtf16 = std::min(s->caretUtf16, static_cast<uint32_t>(s->editingText.size()));
7022	        s->selStartUtf16 = std::min(s->selStartUtf16, static_cast<uint32_t>(s->editingText.size()));
7023	        s->selEndUtf16 = std::min(s->selEndUtf16, static_cast<uint32_t>(s->editingText.size()));
7024	        s->editingProjectionVersion = n.pod.projectionVersion;
7025	        break;
7026	    }
7027	    if (!found) {
7028	        s->pendingImeDetach = true;  // 节点被移除：结束编辑
7029	        s->pendingSettleOnDetach = false;
7030	        s->editing = false;
7031	        s->editorRetired = true;
7032	        s->editingContextLive = false;
7033	        s->previewActive = false;
7034	        s->previewText.clear();
7035	        s->markedActive = false;
7036	        s->reconcileNotifyPending = false;
7037	        cancelProxyRestoreRequest(*s, "node_removed");
7038	    }
7039	}
